UPDATE cargos c
SET id_sial = m.id_sial,
    updated_at = NOW()
FROM mapeo_id_sial m
WHERE c.codigo = m.codigo
  AND c.id_sial IS NULL
  AND c.deleted_at IS NULL;

SELECT COUNT(*) AS actualizados FROM cargos c JOIN mapeo_id_sial m ON m.codigo = c.codigo WHERE c.id_sial = m.id_sial;

COMMIT;
